    `${a.mode}:${a.path}:${a.tokenCount ?? 'null'}`.localeCompare(`${b.mode}:${b.path}:${b.tokenCount ?? 'null'}`),
  );
  const digest = digestCanonicalJson({
    version: 1,
    filesReadFully,
    filesTriagedByName,
    summary,
    events: normalizedDigestEvents,
  });
  return { filesReadFully, filesTriagedByName, summary, digest };
}

